import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 200;
    static final int MAXM = 100000;
    static final int INF = 300000000;

    static int[][] maze_map = new int[20][20];
    static int[][] adjacency = new int[MAXN][MAXN];
    static int n, total_nodes, t;
    static String input_line;
    static int[][] hu_points = new int[MAXN][3], re_points = new int[MAXN][3];
    static int zr, zc;
    static int cx, cy;
    static int[][] dir_moves = {{0, -1}, {0, 1}, {-1, 0}, {1, 0}};

    static int getNodeIndex(int r, int c) {
        if (r > 0 && r <= n && c > 0 && c <= n && maze_map[r][c] != -1)
            return (r - 1) * n + c;
        return -1;
    }

    static void initializeGraph() {
        total_nodes = n * n;
        for (int[] row : adjacency)
            Arrays.fill(row, -1);
        for (int r1 = 1; r1 <= n; r1++) {
            for (int c1 = 1; c1 <= n; c1++) {
                if (maze_map[r1][c1] == -1) continue;
                int p1 = (r1 - 1) * n + c1;
                adjacency[p1][p1] = 0;
                for (int i = 0; i < 4; i++) {
                    int r2 = r1 + dir_moves[i][0];
                    int c2 = c1 + dir_moves[i][1];
                    if (r2 > 0 && r2 <= n && c2 > 0 && c2 <= n && maze_map[r2][c2] != -1) {
                        int p2 = (r2 - 1) * n + c2;
                        adjacency[p1][p2] = 1;
                    }
                }
            }
        }
    }

    static int[] dist_array = new int[MAXN];
    static int[] q_array = new int[MAXM];

    static void computeShortestPaths() {
        int front = 0, rear = 1;
        Arrays.fill(dist_array, INF);
        int start_node = (zr - 1) * n + zc;
        dist_array[start_node] = 0;
        q_array[0] = start_node;
        while (front < rear) {
            int u = q_array[front++];
            for (int v = 1; v <= total_nodes; v++) {
                if (adjacency[u][v] == 1 && dist_array[v] > dist_array[u] + 1) {
                    dist_array[v] = dist_array[u] + 1;
                    q_array[rear++] = v;
                }
            }
        }
    }

    static void allPairsFloyd() {
        for (int k = 1; k <= total_nodes; k++) {
            for (int i = 1; i <= total_nodes; i++) {
                for (int j = 1; j <= total_nodes; j++) {
                    if (adjacency[i][k] != -1 && adjacency[k][j] != -1) {
                        if (adjacency[i][j] == -1 || adjacency[i][j] > adjacency[i][k] + adjacency[k][j]) {
                            adjacency[i][j] = adjacency[i][k] + adjacency[k][j];
                        }
                    }
                }
            }
        }
    }

    static class Edge {
        int from, to, capacity, next;
        public Edge(int from, int to, int capacity, int next) {
            this.from = from;
            this.to = to;
            this.capacity = capacity;
            this.next = next;
        }
    }

    static ArrayList<Edge> flowEdges = new ArrayList<>();
    static int[] head = new int[MAXN];
    static int edgeCount;
    static int sourceNode, sinkNode;

    static void addFlowEdge(int u, int v, int cap) {
        flowEdges.add(new Edge(u, v, cap, head[u]));
        head[u] = flowEdges.size() - 1;
        flowEdges.add(new Edge(v, u, 0, head[v]));
        head[v] = flowEdges.size() - 1;
    }

    static int[] level = new int[MAXN];

    static boolean buildLevelGraph() {
        Arrays.fill(level, -1);
        level[sourceNode] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(sourceNode);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int i = head[u]; i != -1; i = flowEdges.get(i).next) {
                int v = flowEdges.get(i).to;
                if (flowEdges.get(i).capacity > 0 && level[v] == -1) {
                    level[v] = level[u] + 1;
                    q.offer(v);
                }
            }
        }
        return level[sinkNode] != -1;
    }

    static int[] ptr = new int[MAXN];

    static int sendFlow(int u, int flow) {
        if (u == sinkNode) return flow;
        for (int i = ptr[u]; i != -1; i = flowEdges.get(i).next) {
            int v = flowEdges.get(i).to;
            if (flowEdges.get(i).capacity > 0 && level[v] == level[u] + 1) {
                int pushed = sendFlow(v, Math.min(flow, flowEdges.get(i).capacity));
                if (pushed > 0) {
                    flowEdges.get(i).capacity -= pushed;
                    flowEdges.get(i ^ 1).capacity += pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    static int maxFlow() {
        int totalFlow = 0;
        while (buildLevelGraph()) {
            for (int i = 0; i <= total_nodes + 1; i++) {
                ptr[i] = head[i];
            }
            int pushed;
            while ((pushed = sendFlow(sourceNode, INF)) > 0) {
                totalFlow += pushed;
            }
        }
        return totalFlow;
    }

    static int solve() {
        maze_map[zr][zc] = 0;
        initializeGraph();
        computeShortestPaths();
        maze_map[zr][zc] = -1;
        initializeGraph();
        allPairsFloyd();
        flowEdges.clear();
        Arrays.fill(head, -1);
        edgeCount = 0;
        sourceNode = 0;
        sinkNode = cx + cy + 1;
        for (int i = 1; i <= cx; i++) {
            addFlowEdge(sourceNode, i, hu_points[i][2]);
        }
        for (int i = 1; i <= cy; i++) {
            addFlowEdge(cx + i, sinkNode, re_points[i][2]);
        }
        int p = (zr - 1) * n + zc;
        for (int i = 1; i <= cx; i++) {
            for (int j = 1; j <= cy; j++) {
                int p1 = (hu_points[i][0] - 1) * n + hu_points[i][1];
                int p2 = (re_points[j][0] - 1) * n + re_points[j][1];
                if (adjacency[p1][p2] != -1 && adjacency[p1][p2] <= t && adjacency[p1][p2] < dist_array[p2]) {
                    addFlowEdge(i, cx + j, INF);
                } else if (adjacency[p1][p2] != -1 && adjacency[p1][p2] <= t && adjacency[p1][p2] == dist_array[p2]) {
                    for (int z = 0; z < 4; z++) {
                        int rr = re_points[j][0] + dir_moves[z][0];
                        int cc = re_points[j][1] + dir_moves[z][1];
                        int pp = getNodeIndex(rr, cc);
                        if (pp != -1) {
                            if (adjacency[p1][pp] == adjacency[p1][p2] - 1 && adjacency[p1][pp] < dist_array[pp]) {
                                addFlowEdge(i, cx + j, INF);
                            }
                        }
                    }
                }
            }
        }
        return maxFlow();
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());
        cx = 0;
        cy = 0;
        for (int[] row : maze_map)
            Arrays.fill(row, 0);
        for (int i = 1; i <= n; i++) {
            input_line = br.readLine();
            for (int j = 0; j < n; j++) {
                char ch = input_line.charAt(j);
                if (ch == 'Y') maze_map[i][j + 1] = -1;
                else if (ch == 'Z') {
                    zr = i;
                    zc = j + 1;
                    maze_map[i][j + 1] = -1;
                } else if (ch > '0' && ch <= '9') {
                    hu_points[++cx][0] = i;
                    hu_points[cx][1] = j + 1;
                    hu_points[cx][2] = ch - '0';
                }
            }
        }
        for (int i = 1; i <= n; i++) {
            input_line = br.readLine();
            for (int j = 0; j < n; j++) {
                char ch = input_line.charAt(j);
                if (ch > '0' && ch <= '9') {
                    re_points[++cy][0] = i;
                    re_points[cy][1] = j + 1;
                    re_points[cy][2] = ch - '0';
                }
            }
        }
        System.out.println(solve());
    }
}
